import { useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

// Сетка всегда 6 недель, чтобы высота календаря не прыгала при смене месяца.
function buildMonthGrid(view: Date): Date[] {
  const first = new Date(view.getFullYear(), view.getMonth(), 1);
  const shift = (first.getDay() + 6) % 7;
  const start = addDays(first, -shift);
  return Array.from({ length: 42 }, (_, i) => addDays(start, i));
}

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [selected, setSelected] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));
  const [view, setView] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));

  const days = useMemo(() => buildMonthGrid(view), [view]);

  const presets = useMemo(
    () => [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const select = (date: Date) => {
    setSelected(date);
    setView(date);
    onChange(date);
  };

  const shiftMonth = (delta: number) => {
    setView((prev) => new Date(prev.getFullYear(), prev.getMonth() + delta, 1));
  };

  return (
    <Card style={{ padding: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-sm)' }}>
      <Stack direction="column" gap="var(--jx-space-4)">
        <Stack direction="row" gap="var(--jx-space-2)" wrap>
          {presets.map((preset) => (
            <Button
              key={preset.label}
              size="sm"
              variant={isSameDay(selected, preset.date) ? 'primary' : 'secondary'}
              aria-pressed={isSameDay(selected, preset.date)}
              onClick={() => select(preset.date)}
            >
              {preset.label}
            </Button>
          ))}
        </Stack>

        <Stack direction="row" align="center" justify="space-between">
          <Button size="sm" variant="ghost" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
            ‹
          </Button>
          <Text weight="medium" aria-live="polite">
            {MONTHS[view.getMonth()]} {view.getFullYear()}
          </Text>
          <Button size="sm" variant="ghost" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
            ›
          </Button>
        </Stack>

        <div
          role="grid"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-1)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" align="center" color="var(--jx-color-text-muted)">
              {weekday}
            </Text>
          ))}

          {days.map((day) => {
            const outside = day.getMonth() !== view.getMonth();
            const isSelected = isSameDay(day, selected);
            return (
              <Button
                key={day.toISOString()}
                size="sm"
                variant={isSelected ? 'primary' : 'ghost'}
                aria-pressed={isSelected}
                aria-label={day.toLocaleDateString('ru-RU')}
                onClick={() => select(day)}
                style={{
                  width: '100%',
                  color: outside && !isSelected ? 'var(--jx-color-text-muted)' : undefined,
                  borderColor: isSameDay(day, today) && !isSelected ? 'var(--jx-color-border-accent)' : undefined,
                }}
              >
                {day.getDate()}
              </Button>
            );
          })}
        </div>
      </Stack>
    </Card>
  );
}

